-- Tabela oficial de Candidatos TSE 2026
CREATE TABLE IF NOT EXISTS public.tse_candidatos (
    id BIGSERIAL PRIMARY KEY,
    ano_eleicao INTEGER NOT NULL DEFAULT 2026,
    sg_uf VARCHAR(2) NOT NULL,
    nm_ue VARCHAR(100),
    cd_cargo INTEGER,
    ds_cargo VARCHAR(100),
    sq_candidato VARCHAR(25) NOT NULL,
    nr_candidato VARCHAR(10) NOT NULL,
    nm_candidato VARCHAR(255) NOT NULL,
    nm_urna_candidato VARCHAR(255) NOT NULL,
    sg_partido VARCHAR(20),
    nm_partido VARCHAR(100),
    ds_genero VARCHAR(50),
    ds_ocupacao VARCHAR(100),
    foto_url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_tse_cand_uf_nr ON public.tse_candidatos(sg_uf, nr_candidato);
CREATE INDEX IF NOT EXISTS idx_tse_cand_sq ON public.tse_candidatos(sq_candidato);

ALTER TABLE public.tse_candidatos ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir leitura publica dos candidatos TSE" ON public.tse_candidatos;
CREATE POLICY "Permitir leitura publica dos candidatos TSE" ON public.tse_candidatos FOR SELECT USING (true);

